mapper.select:

WHERE ap.article_id = #{articleId}
  AND ap.platform = #{platform}
  AND ap.del_flag = '0'
LIMIT 1

SELECT ap.*, ca.title AS article_title, ca.status AS article_status
FROM article_publish ap
LEFT JOIN content_article ca ON ca.id = ap.article_id AND ca.del_flag = '0'

    ap.del_flag = '0'
    AND ap.article_id = #{articleId}
    AND ap.platform = #{platform}
    AND ap.status = #{status}
    AND ap.is_active = #{isActive}

ORDER BY ap.id DESC
